/**
 * The offer's deep link (sales plan, 2026-10-24): `/settings/plan?offer=1`
 * opens the plans at once where Pro can be sold here — the Plan page
 * brings its picker into view, the free plan opens the Pro sheet. A push,
 * the bell or an e-mail may add `from=push|bell|email`, which names the
 * offer's `opened` event so the funnel knows which message brought the
 * learner; anything else counts as the Plan page. Pure.
 */
import type { ApiOfferEventInput } from '@/api/types.js';

/** Where an opened link may say it came from (the contract's surfaces). */
const FROM = ['push', 'bell', 'email'] as const;

export interface OfferLink {
  asked: boolean;
  surface: ApiOfferEventInput['surface'];
}

export function offerLink(params: URLSearchParams): OfferLink {
  const from = params.get('from');
  const known = FROM.find((one) => one === from);
  return { asked: params.get('offer') === '1', surface: known ?? 'plan' };
}

/** The same address without the link's own parameters, so Back and a reload do not open it again. */
export function withoutOfferLink(params: URLSearchParams): URLSearchParams {
  const next = new URLSearchParams(params);
  next.delete('offer');
  next.delete('from');
  return next;
}

/** Whether an in-app path is the offer's link, for the bell's button words. */
export function isOfferPath(path: string): boolean {
  const [pathname, query = ''] = path.split('?');
  return pathname === '/settings/plan' && offerLink(new URLSearchParams(query.split('#')[0])).asked;
}
